window.pfDiseaseEntries=[
 makeDisease('Arterielle Hypertonie','Herz-Kreislauf','Dauerhaft erhöhter Blutdruck belastet Gefäße und Organe. Eine einzelne Messung reicht für die Diagnose nicht aus.','Primäre Hypertonie ist häufig multifaktoriell; sekundäre Formen können durch andere Erkrankungen oder Arzneimittel entstehen. Langfristig steigen Risiken für Herz, Gehirn, Nieren und Augen.',['Oft lange ohne Beschwerden; sehr hohe Werte können Kopfschmerz, Sehstörungen, Brustschmerz oder neurologische Ausfälle begleiten.','Akuter Brustschmerz, Atemnot, Bewusstseins- oder Sprachstörung sind Notfallzeichen, nicht bloß ein Zahlenproblem.'],['Messung mit passender Manschette und Ruhephase wiederholen; Verlauf und häusliche Messungen ärztlich einordnen lassen.','Ursachen, Begleiterkrankungen und Medikamente werden ärztlich geprüft; Therapieziele werden individuell vereinbart.'],['Messbedingungen, Symptome, Schwindel, Sturzrisiken und verordnete Therapie erfassen.','Auf regelmäßige Einnahme nach Verordnung und mögliche Nebenwirkungen achten; Änderungen nicht eigenständig vornehmen.','Bewegung, Ernährung, Rauchstopp und Stressbewältigung als gemeinsam vereinbarte Gesundheitsziele besprechen.'],'Plötzlich auftretende neurologische Ausfälle, akuter Brustschmerz oder schwere Atemnot erfordern sofortige Notfallhilfe.','Eine Bewohnerin hat wiederholt hohe Messwerte und berichtet über Schwindel beim Aufstehen. Welche Messbedingungen, Risiken und nächsten Schritte klärst du?','hypertension',['Was ist bei einem einzelnen hohen Blutdruckwert am sinnvollsten?',['Sofort eigenständig die Dosis verdoppeln','Messung korrekt wiederholen, Beschwerden erfassen und Verlauf fachlich weitergeben','Wert ignorieren','Alle Medikamente absetzen'],1,'Einzelmessung und Situation prüfen; Therapieentscheidungen richten sich nach Verlauf, Beschwerden und ärztlicher Anordnung.']),
 makeDisease('Koronare Herzkrankheit und akutes Koronarsyndrom','Herz-Kreislauf','Bei der koronaren Herzkrankheit verengen Ablagerungen die Herzkranzgefäße. Ein akuter Gefäßverschluss kann einen Herzinfarkt auslösen.','Risikofaktoren sind unter anderem Rauchen, Hypertonie, Diabetes und Fettstoffwechselstörungen. Bei Frauen, älteren Menschen und Menschen mit Diabetes können Beschwerden atypisch sein.',['Druck oder Enge im Brustkorb, Ausstrahlung, Atemnot, Übelkeit, kalter Schweiß oder plötzliche Schwäche.','Neue oder anhaltende Beschwerden, Kreislaufinstabilität und Bewusstseinsveränderung sind akut abklärungsbedürftig.'],['Bei Verdacht unverzüglich Notfallteam/112 nach Setting alarmieren; Beginn der Beschwerden und Verlauf festhalten.','EKG, Labor und weitere Diagnostik erfolgen durch das Behandlungsteam; ein frühes unauffälliges Einzelresultat schließt einen Infarkt nicht sicher aus.'],['Person nicht allein lassen, ABCDE und Vitalzeichen nach Qualifikation überwachen; Ruhe und sichere Position ermöglichen.','Schmerz, Atemnot, Angst, Zeitpunkt des Beginns und Maßnahmen strukturiert übergeben.','Medikamente nur nach gültiger Anordnung geben und Wirkung/Nebenwirkungen beobachten.'],'Neue Brustenge, Atemnot, kalter Schweiß, Kollaps oder plötzlich atypische starke Schwäche sofort als möglichen Notfall behandeln.','Ein Patient wird beim Waschen blass, kaltschweißig und klagt über Druck im Brustkorb. Was hat Vorrang und welche Angaben gehören in die Übergabe?','coronary',['Was hat bei neuem Brustdruck mit Kaltschweißigkeit Vorrang?',['Erst die Körperpflege beenden','Notfallhilfe organisieren, bei der Person bleiben und strukturiert beurteilen','Eine Mahlzeit anbieten','Beschwerden als Angst bewerten'],1,'Akutes Koronarsyndrom ist möglich; rasche Eskalation darf nicht durch Routinetätigkeiten verzögert werden.']),
 makeDisease('Herzinsuffizienz','Herz-Kreislauf','Das Herz kann den Körper nicht ausreichend mit Blut versorgen oder benötigt dafür erhöhte Füllungsdrücke. Die Erkrankung kann akut oder chronisch verlaufen.','Pumpfunktion und Füllung können unterschiedlich beeinträchtigt sein. Häufige Ursachen sind koronare Herzkrankheit, Hypertonie und Klappenerkrankungen.',['Belastungs- oder Ruhedyspnoe, Müdigkeit, Ödeme, Gewichtszunahme und eingeschränkte Belastbarkeit.','Rasche Verschlechterung, Atemnot in Ruhe, Zyanose, neue Verwirrtheit oder Kollaps erfordern sofortige Hilfe.'],['Diagnostik umfasst je nach Situation Untersuchung, EKG, Labor und Echokardiografie.','Medikamente, Flüssigkeits- und Salzempfehlungen richten sich nach individuellem Plan; keine pauschale Trinkmengenbegrenzung.'],['Atemnot, Atemfrequenz, Ödeme, Gewichtstrend, Ausscheidung, Schlafposition und Belastbarkeit vergleichen.','Tägliches Wiegen nur nach Versorgungsplan; gleiche Bedingungen und auffällige Veränderungen weitergeben.','Energie einteilen, Pausen ermöglichen und Selbstmanagement mit Warnzeichenplan fördern.'],'Akute Atemnot, schaumiger Auswurf, Kreislaufabfall oder Bewusstseinsstörung sofort eskalieren.','Eine Patientin mit Herzinsuffizienz nimmt binnen weniger Tage deutlich zu und bekommt nachts schlechter Luft. Welche Veränderungen erhebst du und wie reagierst du?','heartFailure',['Welche Beobachtung ist bei Herzinsuffizienz im Verlauf besonders hilfreich?',['Ein einzelner Pulswert ohne Kontext','Gewichtstrend zusammen mit Atemnot, Ödemen und Ausscheidung','Nur die Trinkmenge eines Tages','Nur die Hautfarbe'],1,'Veränderungen müssen gemeinsam bewertet und nach individuellem Behandlungsplan weitergegeben werden.']),
 makeDisease('Vorhofflimmern','Herz-Kreislauf','Vorhofflimmern ist eine häufige Herzrhythmusstörung mit ungeordneter elektrischer Aktivität der Vorhöfe. Sie erhöht das Risiko für Schlaganfall und kann die Kreislaufleistung beeinträchtigen.','Verlauf und Beschwerden reichen von kaum bemerktem Rhythmus bis zu deutlichem Herzrasen. Schlaganfallrisiko und Behandlung werden ärztlich individuell bewertet.',['Unregelmäßiger Puls, Herzklopfen, Müdigkeit, Schwindel oder Atemnot; manche Betroffene haben keine Symptome.','Neu auftretende Lähmung, Sprachstörung, Gesichtslähmung oder plötzlicher Sehverlust: Schlaganfallverdacht.'],['Puls und Beschwerden erfassen; EKG und Ursachenabklärung veranlasst das Behandlungsteam.','Gerinnungshemmung und Frequenz-/Rhythmuskontrolle sind individuelle ärztliche Entscheidungen.'],['Bei Veränderungen Kreislauf, Bewusstsein, Atemnot und Puls beobachten und zeitnah melden.','Bei Antikoagulation auf Blutungszeichen achten und Sturzereignisse melden; Medikamente nicht eigenständig pausieren.','Wissen zu Einnahme, Kontrollen und Notfallzeichen in verständlicher Sprache prüfen.'],'Schlaganfallzeichen, Synkope, Brustschmerz oder schwere Atemnot erfordern sofortige Notfallhilfe.','Ein Bewohner mit bekanntem Vorhofflimmern wirkt plötzlich verwirrt und hat eine hängende Mundpartie. Was tust du zuerst?','guidelines',['Was ist bei plötzlichen fokalen Ausfällen bei Vorhofflimmern wichtig?',['Erst den nächsten regulären Termin abwarten','Schlaganfallverdacht sofort alarmieren und Beginn der Symptome festhalten','Zusätzliche Antikoagulation eigenständig geben','Den Bewohner schlafen lassen'],1,'Schlaganfall ist ein zeitkritischer Notfall; Behandlung und Medikamente nicht eigenständig ändern.']),
 makeDisease('Schlaganfall und TIA','Neurologie','Ein Schlaganfall entsteht durch eine Durchblutungsstörung oder Blutung im Gehirn. Eine TIA verursacht vorübergehende fokale Ausfälle und ist ebenfalls ein dringendes Warnsignal.','Durch Hirnschädigung können Motorik, Sprache, Wahrnehmung, Schlucken, Denken und Emotionen betroffen sein. Akutbehandlung ist zeitkritisch.',['FAST: Gesicht, Arm, Sprache, Zeit; auch Sehstörung, Gleichgewichtsverlust oder plötzlich stärkster Kopfschmerz beachten.','Bei jedem neuen Verdacht sofort 112/innerklinisches Notfallteam; Zeitpunkt des letzten sicheren Normalzustands notieren.'],['Notfallteam organisiert Bildgebung und entscheidet über Akuttherapie. Pflege erhebt Beginn, Symptome, Vitalwerte und relevante Vorgeschichte.','Vor Essen, Trinken und oraler Medikation Schluckfähigkeit nach geltendem Screening-/Behandlungsstandard klären.'],['ABCDE, neurologische Veränderung und Vitalwerte nach Qualifikation beobachten; nichts oral geben, bis Schlucken sicher beurteilt ist.','Lagerung, Mobilisation, Kommunikation und Hilfsmittel an Befund und Anordnung anpassen.','Rehabilitation, Angehörigenberatung und sichere Entlassung interprofessionell vorbereiten.'],'Plötzliche Gesichtslähmung, Armschwäche, Sprach- oder Sehstörung sofort als Notfall behandeln, auch wenn sie wieder verschwindet.','Ein Patient spricht plötzlich verwaschen und kann den rechten Arm nicht halten. Welche Zeitangabe, Beobachtungen und Sofortmaßnahmen sind wichtig?','stroke',['Eine vorübergehend verschwundene Sprachstörung bedeutet …',['Entwarnung','mögliche TIA und dringenden Abklärungsbedarf','nur Müdigkeit','keine weitere Maßnahme'],1,'Auch rückläufige fokale Ausfälle müssen dringend medizinisch abgeklärt werden.']),
 makeDisease('Parkinson-Krankheit','Neurologie','Parkinson ist eine fortschreitende neurologische Erkrankung mit Bewegungsverlangsamung und weiteren motorischen sowie nichtmotorischen Symptomen.','Dopaminerge Nervenzellen gehen zugrunde. Verlauf, Symptome und Wirkungsschwankungen sind individuell; Medikamente sollen zu den festgelegten Zeiten gegeben werden.',['Bradykinese, Rigor, Ruhetremor oder Gleichgewichtsstörung; möglich sind Freezing, leise Stimme, Obstipation, Schlaf- und Stimmungssymptome.','Stürze, Schluckprobleme, plötzliche starke Bewegungsverschlechterung und Verwirrtheit abklären.'],['Neurologische Diagnose und Therapie erfolgen ärztlich. Pflege beobachtet Beweglichkeit, Alltagsfunktion, Schlucken und zeitlichen Bezug zur Medikation.','Verordnete Einnahmezeiten und Darreichungsform genau beachten; Änderungen nur ärztlich abstimmen.'],['Medikamente pünktlich nach Plan richten und verspätete/ausgelassene Gaben sofort klären.','Transfers sichern, Zeit geben, Freezing nicht durch Ziehen oder Hast verstärken; geeignete Strategien im Team abstimmen.','Bei Husten beim Trinken pausieren und Schluckabklärung organisieren; Kost nicht pauschal verändern.'],'Akute neue Bewusstseinsstörung, Atemnot, schweres Verschlucken oder plötzliche deutliche Verschlechterung sofort melden.','Ein Bewohner friert beim Gehen ein, ist zweimal gestürzt und hustet beim Trinken. Welche Risiken, Ressourcen und nächsten Schritte benennst du?','parkinson',['Was ist bei Parkinson-Medikamenten im Pflegealltag besonders wichtig?',['Einnahmezeiten eigenständig verändern','Verordnete Zeiten beachten und Verzögerungen sofort klären','Medikation bei guter Beweglichkeit auslassen','Tabletten immer mörsern'],1,'Zeitpunkt und Darreichungsform der individuellen Verordnung beachten; nicht eigenständig verändern.']),
 makeDisease('Demenz','Neurologie und Gerontopsychiatrie','Demenz bezeichnet ein erworbenes, meist fortschreitendes Syndrom mit kognitiven Einschränkungen, die Alltag und Selbstständigkeit beeinträchtigen.','Alzheimer ist eine häufige Ursache; weitere Formen sind vaskulär, Lewy-Körper- und frontotemporal. Demenz ist nicht einfach normales Altern.',['Gedächtnis, Orientierung, Sprache, Planung oder Verhalten verändern sich meist über längere Zeit.','Plötzliche deutliche Verschlechterung ist kein typischer normaler Verlauf und kann auf ein zusätzliches Delir oder eine akute Erkrankung hinweisen.'],['Ursachen und behandelbare Mitfaktoren werden ärztlich abgeklärt. Verlauf, Alltagsfunktion und Belastungen der Bezugspersonen gehören zur Einschätzung.','Medikamentöse und nichtmedikamentöse Behandlung wird individuell abgestimmt.'],['Biografie, Gewohnheiten, Fähigkeiten, Bedürfnisse und Risiken erfassen; vertraute Orientierungshilfen nutzen.','Einfach, respektvoll und in kurzen Schritten kommunizieren; Wahlmöglichkeiten anbieten und Selbstständigkeit erhalten.','Angehörige mit Zustimmung einbeziehen und Entlastungsangebote vermitteln.'],'Akute Verwirrtheit, Fieber, Atemnot, Sturz oder neue neurologische Symptome müssen sofort auf zusätzliche Ursachen geprüft werden.','Eine Bewohnerin mit Demenz ist seit heute deutlich unaufmerksamer und trinkt wenig. Wie unterscheidest du Ausgangszustand und akute Veränderung?','dementia',['Was spricht eher für ein zusätzliches Delir?',['Langsame Veränderung über Jahre','Plötzliche fluktuierende Aufmerksamkeitsstörung','Eine langjährige Gedächtnislücke allein','Unveränderte Alltagsfähigkeit'],1,'Akuter Beginn und schwankende Aufmerksamkeit verlangen eine zeitnahe medizinische Ursachenklärung.']),
 makeDisease('Delir','Neurologie und Gerontopsychiatrie','Ein Delir ist eine akute, meist fluktuierende Störung von Aufmerksamkeit und Bewusstsein, verursacht durch eine körperliche oder medikamentöse Belastung.','Mögliche Auslöser sind Infektion, Hypoxie, Schmerz, Dehydratation, Stoffwechselstörung, Operation oder Arzneimittel. Ein Delir kann hypoaktiv und deshalb leicht übersehen sein.',['Plötzlicher Beginn, wechselnde Orientierung, Unruhe oder ungewöhnliche Schläfrigkeit, gestörter Schlaf-Wach-Rhythmus.','Fieber, niedriger Blutdruck, Hypoxie, Unterzuckerung oder fokale neurologische Zeichen sind dringlich.'],['Ausgangszustand und zeitlichen Verlauf mit Angehörigen/Team klären. Vitalwerte, Medikamente, Schmerz, Ausscheidung und mögliche Auslöser erheben.','Ärztliche Abklärung der Ursache und gezielte Behandlung sind entscheidend; Delir ist keine eigenständige Demenzdiagnose.'],['Bei akuter Veränderung sofort Pflegefachperson/ärztlichen Dienst informieren und ABCDE/Vitalzeichen nach Standard erheben.','Reize angemessen steuern, Brille/Hörgerät und Orientierung anbieten, Schlaf und sichere Mobilität fördern.','Fixierungen und sedierende Mittel nicht routinemäßig einsetzen; Ursache, Gefahren und mildere Maßnahmen prüfen.'],'Akute Verwirrtheit mit Kreislauf-, Atem- oder Bewusstseinsstörung sofort eskalieren.','Ein älterer Patient ist nach der Operation plötzlich schläfrig und antwortet verzögert. Welche Sofortbeurteilung und Informationsquellen brauchst du?','dementia',['Was ist bei neuem Delirverdacht zentral?',['Nur die Demenzdiagnose dokumentieren','Akute Ursache suchen und Zustand zeitnah medizinisch beurteilen lassen','Die Person automatisch fixieren','Flüssigkeit ohne Prüfung stark begrenzen'],1,'Delir ist ein akut behandlungsbedürftiges Syndrom; Auslöser und Risiken müssen individuell abgeklärt werden.']),
 makeDisease('Epilepsie und epileptischer Anfall','Neurologie','Epilepsie ist eine Erkrankung mit anhaltender Neigung zu epileptischen Anfällen. Ein einzelner Anfall bedeutet nicht automatisch Epilepsie.','Anfälle können motorisch, sensorisch, vegetativ oder mit Bewusstseinsstörung auftreten. Dauer, Verlauf und Erholung sind für die Einordnung wichtig.',['Während eines Anfalls vor Verletzung schützen, Umgebung sichern und Zeit messen.','Anfall über fünf Minuten, wiederholte Anfälle ohne Erholung, Verletzung, Atemproblem, Schwangerschaft oder erster Anfall: Notfallhilfe.'],['Anfallsbeschreibung, Dauer, Auslöser, Bewusstsein und Erholungsphase dokumentieren. Diagnostik und antikonvulsive Therapie erfolgen ärztlich.','Notfallmedikamente nur nach individuellem Plan und eigener Qualifikation anwenden.'],['Nicht festhalten, nichts in den Mund stecken und keine orale Flüssigkeit geben. Nach dem Anfall Atmung/Bewusstsein prüfen und bei normaler Atmung sichere Seitenlage erwägen.','Würde und Privatsphäre schützen; Betroffene nach der Erholung orientieren und informieren.'],'Anhaltender oder wiederkehrender Anfall ohne Erholung, Atemstörung oder Verletzung sofort als Notfall behandeln.','Eine Bewohnerin krampft seit über fünf Minuten und wird zwischen den Anfällen nicht wach. Welche Maßnahmen sind sicher und welche unterlässt du?','guidelines',['Was ist während eines generalisierten Krampfanfalls richtig?',['Kiefer öffnen und Gegenstand zwischen die Zähne schieben','Vor Verletzungen schützen, Zeit messen und bei langem Anfall Hilfe rufen','Arme und Beine festhalten','Wasser einflößen'],1,'Schutz, Zeitmessung und zeitgerechte Eskalation; nichts in den Mund und keine gewaltsame Fixierung.']),
 makeDisease('Asthma bronchiale','Atmung','Asthma ist eine chronisch entzündliche Erkrankung der Atemwege mit variabler Atemwegsverengung und Überempfindlichkeit.','Beschwerden können durch Allergene, Infekte, Belastung oder andere Auslöser zunehmen. Verlauf und Auslöser unterscheiden sich zwischen Personen.',['Anfallsweise Atemnot, pfeifende Ausatmung, Husten und Brustenge; zwischen Episoden kann die Lungenfunktion besser sein.','Sprechunfähigkeit, Erschöpfung, Zyanose, Bewusstseinsveränderung oder fehlende Besserung nach Notfallplan sind Alarmzeichen.'],['Diagnose und Stufentherapie erfolgen ärztlich; Inhalationstechnik und schriftlicher Asthma-Aktionsplan regelmäßig prüfen.','Bei akutem Anfall Therapie nach individuellem Plan und Notfallstandard unterstützen; keine pauschale Arzneimitteländerung.'],['Atemarbeit, Sprechfähigkeit, Bewusstsein, SpO₂ nach Standard, Auslöser und Wirkung der verordneten Inhalation beobachten.','Aufrechte Position, Ruhe und atemerleichternde Umgebung anbieten; bei fehlender Besserung eskalieren.','Inhalator und Spacer praktisch üben lassen; Verständnis per Rückerklärung prüfen.'],'Schwere Atemnot, Erschöpfung, Zyanose, Bewusstseinsstörung oder fehlende Wirkung des Notfallplans sofort eskalieren.','Ein Jugendlicher mit Asthma kann kaum ganze Sätze sprechen; sein Spray liegt bereit. Wie priorisierst du Einschätzung, Hilfe und den individuellen Notfallplan?','asthma',['Was ist bei einem schweren Asthmaanfall richtig?',['Atemnot als Angst abtun','Notfallstandard aktivieren, Atemzustand überwachen und individuellen Plan unterstützen','Zum Hinlegen zwingen','Inhalation grundsätzlich verbieten'],1,'Schwere Atemnot ist zeitkritisch; Behandlung folgt Verordnung und Notfallstandard.']),
 makeDisease('Pneumonie','Atmung und Infektionen','Eine Pneumonie ist eine Entzündung des Lungengewebes, meist durch Infektionserreger. Schwere und Verlauf hängen von Ursache, Alter und Vorerkrankungen ab.','Erreger können durch Tröpfchen/Aerosole oder Aspiration in die unteren Atemwege gelangen. Gebrechliche Menschen zeigen oft unspezifische Zeichen.',['Husten, Fieber oder Untertemperatur, Atemnot, Auswurf, pleuritischer Schmerz, Schwäche oder neue Verwirrtheit.','Atemfrequenzanstieg, Hypoxie, niedriger Blutdruck, Zyanose oder Bewusstseinsstörung sprechen für schwere Erkrankung.'],['Diagnostik erfolgt klinisch und je nach Situation mit Bildgebung, Labor und mikrobiologischen Proben.','Antibiotika sind nur bei entsprechender Indikation und ärztlicher Entscheidung; Erreger und Verlauf beachten.'],['Atemfrequenz, Atemarbeit, Temperatur, Bewusstsein, Sauerstoffsättigung und Trink-/Essfähigkeit im Verlauf beobachten.','Aufrechte Position, Mobilisation nach Verträglichkeit, Mundpflege und Sekretmanagement nach Plan unterstützen.','Bei Schluckrisiko Aspiration prüfen und Team informieren; Isolation/Hygiene nach Erreger und Hausstandard.'],'Schnell zunehmende Atemnot, Zyanose, Hypotonie oder neue Bewusstseinsstörung sofort eskalieren.','Ein älterer Bewohner hustet seit Tagen, ist heute ungewöhnlich schläfrig und atmet schneller. Welche akute Einschätzung ist nötig?','guidelines',['Welche Veränderung kann bei älteren Menschen auf eine schwere Pneumonie hinweisen?',['Nur ein produktiver Husten','Neue Verwirrtheit zusammen mit schneller Atmung','Appetit auf Suppe','Chronische Rückenschmerzen'],1,'Unspezifische akute Veränderungen können eine schwere Infektion anzeigen und verlangen die Beurteilung des Gesamtzustands.']),
 makeDisease('Sepsis und septischer Schock','Infektionen und Notfälle','Sepsis ist eine lebensbedrohliche Organdysfunktion infolge einer fehlregulierten Reaktion auf eine Infektion. Sie kann sich rasch verschlechtern.','Ausgangspunkt kann unter anderem Lunge, Harnwege, Bauch, Haut oder ein Katheter sein. Fieber kann fehlen; frühe Warnzeichen sind oft unspezifisch.',['Neue Verwirrtheit, schnelle Atmung, Kreislaufabfall, kalte/marmorierte Haut, geringe Urinausscheidung oder rasche Verschlechterung.','Ein einzelner Score oder ein normaler Temperaturwert schließt Sepsis nicht aus.'],['Früherkennung, sofortige Teameskalation und strukturierte Diagnostik sind zentral. Blutkulturen, Labor und Bildgebung organisiert das Behandlungsteam.','Antibiotika, Flüssigkeit und Kreislauftherapie erfolgen nach ärztlichem Sepsisstandard; Pflege verzögert Alarmierung nicht.'],['Bei Verdacht unverzüglich Hilfe alarmieren, ABCDE/Vitalwerte erheben und Verlauf mit Zeitpunkten dokumentieren.','Ausscheidung, Hautperfusion, Bewusstsein und Atmung eng beobachten; Veränderungen strukturiert per SBAR übergeben.','Hygiene und Fokus-/Katheterkontrolle nach Standard durchführen; nach überstandener Sepsis mögliche Langzeitfolgen beachten.'],'Neue Organfunktionsstörung bei möglicher Infektion ist ein Notfall. Nicht auf Fieber oder einen bestimmten Score warten.','Ein Patient mit Harnwegsinfekt wird plötzlich verwirrt, atmet schnell und hat kaum Urin ausgeschieden. Welche ersten Schritte und Übergabe sind nötig?','sepsis',['Was ist bei möglicher Sepsis wichtig?',['Auf Fieber warten','Akute Verschlechterung sofort eskalieren und ABCDE/Vitalwerte erheben','Nur Temperatur dokumentieren','Abwarten, ob Antibiotika wirken'],1,'Sepsis kann ohne Fieber auftreten; frühe Eskalation und strukturierte Beurteilung sind entscheidend.']),
 makeDisease('Diabetes mellitus Typ 1 und Typ 2','Stoffwechsel','Diabetes mellitus ist eine chronische Stoffwechselerkrankung mit dauerhaft erhöhtem Blutzucker. Typ 1 und Typ 2 unterscheiden sich in Entstehung und Therapie.','Typ 1 beruht auf weitgehendem Insulinmangel; Typ 2 auf Insulinresistenz und im Verlauf relativer Insulinsekretionsstörung. Behandlung wird individualisiert.',['Hyperglykämie kann Durst, häufiges Wasserlassen, Müdigkeit und verschwommenes Sehen verursachen. Hypoglykämie kann Schwitzen, Zittern, Verwirrtheit oder Bewusstseinsstörung auslösen.','Übelkeit, Bauchschmerz, tiefe schnelle Atmung, Erbrechen oder Bewusstseinsstörung können einen akuten Notfall anzeigen.'],['Diagnose und Therapieziele sind ärztlich; Blutzuckermessung und Verlauf nach individuellem Plan.','Insulinart, Mahlzeiten, Nierenfunktion und Krankheitstage beeinflussen das Management; Dosen nie eigenständig ändern.'],['Bei Hypoglykämie zuerst Bewusstsein und sicheres Schlucken beurteilen; bei unsicherem Schlucken nichts oral geben und Hilfe holen.','Injektionsstellen, Fußhaut, Ernährung, Flüssigkeit und Medikamenteneinnahme nach individuellem Plan beobachten.','Selbstmanagement und Notfallplan üben; Gesundheitskompetenz und persönliche Ziele berücksichtigen.'],'Bewusstseinsstörung, nicht sicheres Schlucken, Erbrechen mit tiefer Atmung oder Kreislaufprobleme erfordern sofortige Notfallhilfe.','Ein Patient mit Insulintherapie ist schwitzig, verwirrt und hustet beim Trinken. Welche Sicherheitsentscheidung hat Vorrang?','diabetes',['Bei Verwirrtheit und nicht sicherem Schlucken während einer Hypoglykämie …',['Saft einflößen','Keine orale Gabe, Hilfe alarmieren und Notfallplan nutzen','Insulin nachspritzen','Abwarten'],1,'Bei unsicherem Schlucken besteht Aspirationsgefahr; Behandlung nach Notfallplan und Qualifikation.']),
 makeDisease('Chronische Nierenerkrankung und Dialyse','Niere und Stoffwechsel','Bei chronischer Nierenerkrankung bleibt die Nierenfunktion längerfristig vermindert oder es bestehen Hinweise auf Nierenschädigung. Fortschreiten und Symptome sind variabel.','Häufige Ursachen sind Diabetes und Hypertonie. Spät können Wasser-, Elektrolyt- und Säure-Basen-Haushalt sowie Blutbildung und Knochenstoffwechsel betroffen sein.',['Früh oft keine Beschwerden; später Müdigkeit, Ödeme, Juckreiz, Appetitverlust, Übelkeit oder veränderte Urinmenge.','Atemnot durch Überwässerung, Brustschmerz, Verwirrtheit oder Muskelschwäche können dringliche Komplikationen anzeigen.'],['eGFR und Albuminurie werden im Verlauf beurteilt. Medikamente und Begleiterkrankungen beeinflussen die Therapie.','Dialyseverfahren und individuelle Flüssigkeits-/Ernährungsziele werden mit dem Behandlungsteam festgelegt.'],['Gewicht, Ödeme, Blutdruck, Ausscheidung, Haut, Übelkeit und Belastbarkeit im Verlauf erfassen.','Bei Dialyse Zugang schützen und auf Infektion, Blutung, Schwellung oder Funktionsänderung achten; keine pauschalen Einschränkungen verordnen.','Medikamente einschließlich frei verkäuflicher Mittel mit Nierenfunktion abgleichen lassen.'],'Akute Atemnot, deutlich reduzierte Urinausscheidung, Brustschmerz oder neue Bewusstseinsstörung sofort melden.','Ein Dialysepatient kommt nach Hause und hat Fieber, Schmerzen und eine gerötete Fistelregion. Welche Beobachtungen und Schritte priorisierst du?','kidney',['Welche Maßnahme schützt einen Dialysezugang?',['Zugang routinemäßig für Blutdruckmessung nutzen','Zugang auf Infektions-/Funktionszeichen prüfen und lokale Schutzregeln beachten','Bei jeder Rötung selbst Antibiotika beginnen','Zugang ohne Anordnung komprimieren'],1,'Gefäßzugänge müssen nach individuellem Dialyse- und Hygienestandard beobachtet und geschützt werden.']),
 makeDisease('Harnwegsinfektion','Niere und Infektionen','Harnwegsinfektionen reichen von einer Blasenentzündung bis zur Nierenbeckenentzündung oder systemischen Infektion. Symptome und Schwere unterscheiden sich.','Risikofaktoren sind unter anderem Katheter, Abflussstörung, Schwangerschaft und bestimmte Vorerkrankungen. Bakterien im Urin ohne Beschwerden bedeuten nicht automatisch eine behandlungsbedürftige Infektion.',['Dysurie, häufiges Wasserlassen und suprapubischer Schmerz; Fieber, Flankenschmerz und Schüttelfrost können für obere Infektion sprechen.','Bei älteren Menschen ist Verwirrtheit allein unspezifisch; Ausgangszustand und andere Ursachen mitprüfen.'],['Symptome, Vitalwerte und Urinbefund im Kontext beurteilen; Diagnostik und Antibiotikatherapie ärztlich nach Indikation.','Katheterindikation regelmäßig prüfen; aseptische Manipulation und lokale Standards beachten.'],['Schmerz, Temperatur, Flüssigkeitsaufnahme, Ausscheidung und Allgemeinzustand erfassen.','Intimsphäre wahren; Trinkempfehlung an individuelle Einschränkungen und Behandlung anpassen.','Bei Katheter Beschwerden und Durchfluss prüfen, aber keine Routine-Manipulation oder Spülung ohne Plan.'],'Fieber mit Schüttelfrost, Flankenschmerz, Hypotonie oder rascher Verschlechterung sofort ärztlich abklären lassen.','Eine Bewohnerin ist seit heute verwirrt, aber ohne bekannte Harnwegsbeschwerden. Welche weiteren Ursachen und Befunde musst du prüfen?','urinary',['Verwirrtheit bei einer älteren Person bedeutet automatisch …',['Harnwegsinfektion','eine unspezifische Veränderung, die ganzheitlich abgeklärt werden muss','Antibiotikapflicht','Demenzprogression'],1,'Verwirrtheit allein beweist keine Harnwegsinfektion; Symptome, Befunde und Alternativursachen prüfen.']),
 makeDisease('Tiefe Venenthrombose und Lungenembolie','Gefäße und Notfälle','Eine tiefe Venenthrombose ist ein Blutgerinnsel in einer tiefen Vene. Löst es sich und verschließt Lungengefäße, entsteht eine Lungenembolie.','Risiken sind unter anderem Immobilität, Operation, Krebs, Schwangerschaft und frühere VTE. Risikoabschätzung und Prophylaxe richten sich nach Situation und Blutungsrisiko.',['Einseitige Schwellung, Schmerz, Überwärmung oder Spannungsgefühl können bei TVT auftreten, sind aber nicht beweisend.','Plötzliche Atemnot, Brustschmerz, Tachykardie, Synkope oder Bluthusten sprechen für mögliche Lungenembolie.'],['Diagnose durch klinische Einschätzung und ärztliche Bildgebung/Labor. Prophylaxe und Antikoagulation nur nach individuellem Risiko- und Therapieplan.','Kompressionsmaßnahmen werden indikationsgerecht festgelegt; prophylaktische Maßnahmen nicht eigenmächtig verändern.'],['Bewegung nach Plan fördern und auf neue einseitige Schwellung oder Atemnot achten.','Verdächtige Extremität nicht massieren; bei möglicher Embolie sofort Notfallhilfe alarmieren.','Blutungszeichen bei Antikoagulation beobachten und Stürze zeitnah melden.'],'Plötzliche Atemnot, Brustschmerz, Synkope oder Kreislaufabfall können eine Lungenembolie anzeigen: sofort Notfallhilfe.','Nach einer Operation entwickelt ein Patient einseitige Wadenschwellung und plötzlich Atemnot. Welche Priorität haben beide Befunde?','vte',['Was ist bei neuem Verdacht auf Lungenembolie richtig?',['Wade massieren und abwarten','Sofort Notfallhilfe alarmieren und Atmung/Kreislauf beurteilen','Zur Bewegung auffordern','Kompression eigenständig erhöhen'],1,'Mögliche Embolie ist zeitkritisch; keine Massage und keine eigenständige Therapieänderung.']),
 makeDisease('Osteoporose und hüftnahe Fraktur','Bewegungsapparat','Osteoporose vermindert Knochenfestigkeit und erhöht das Risiko für Fragilitätsfrakturen. Hüftnahe Frakturen führen oft zu Schmerzen und Funktionsverlust.','Alter, frühere Frakturen, bestimmte Erkrankungen und Medikamente beeinflussen das Risiko. Stürze und Knochenbrüchigkeit wirken zusammen.',['Nach Sturz Hüft-/Leistenschmerz, Unfähigkeit aufzutreten, Beinverkürzung oder Außenrotation; bei älteren Menschen auch atypische Zeichen.','Sturz ohne offensichtliche Verletzung schließt Fraktur nicht aus, besonders bei anhaltendem Schmerz oder Funktionsverlust.'],['Frakturdiagnostik erfolgt ärztlich mittels Untersuchung und Bildgebung; Operation und Mobilisation richten sich nach Befund.','Osteoporosebehandlung und Sekundärprävention werden individuell geplant.'],['Nach Sturz nicht vorschnell aufrichten; Schmerz, Bewusstsein, Kopfverletzung, Antikoagulation und Durchblutung/Sensibilität erfassen.','Schmerztherapie nach Anordnung, Delirprävention, frühe sichere Mobilisation und Ernährung/Flüssigkeit nach Plan unterstützen.','Sturzursachen und Hilfsmittel gemeinsam überprüfen; Angst vor erneutem Sturz ernst nehmen.'],'Starke Schmerzen, Fehlstellung, Kreislaufprobleme oder möglicher Kopfaufprall unter Antikoagulation erfordern dringende Abklärung.','Eine ältere Frau kann nach einem Sturz nicht mehr auftreten und nimmt einen Gerinnungshemmer. Welche Informationen und Sicherheitsmaßnahmen sind wichtig?','osteoporosis',['Was ist nach Sturz mit möglicher Hüftfraktur zu tun?',['Sofort eigenständig aufrichten','Nicht unnötig bewegen, Zustand und Verletzungszeichen prüfen und Hilfe organisieren','Schmerz ignorieren, wenn keine Wunde sichtbar ist','Nur die Gehfähigkeit testen'],1,'Mögliche Fraktur und zusätzliche Risiken erfordern vorsichtige Beurteilung und fachliche Hilfe.']),
 makeDisease('Kolorektales Karzinom und Stoma','Onkologie und Verdauung','Kolorektales Karzinom entsteht im Dick- oder Enddarm. Operationen können vorübergehend oder dauerhaft ein Stoma erforderlich machen.','Risikofaktoren und Beschwerden sind vielfältig; Vorsorge und Früherkennung können relevant sein. Diagnose und Therapie erfolgen interprofessionell.',['Veränderte Stuhlgewohnheiten, Blut im Stuhl, Bauchbeschwerden, Müdigkeit durch Anämie oder ungewollter Gewichtsverlust abklären.','Akute starke Schmerzen, Erbrechen, geblähter Bauch oder fehlender Stomastuhl können auf einen Notfall hinweisen.'],['Diagnostik umfasst je nach Situation Endoskopie, Histologie und Bildgebung. Therapie kann Operation, medikamentöse Tumortherapie und Nachsorge beinhalten.','Stomaversorgung wird an Stomaart, Haut, Ausscheidung und Selbstständigkeit angepasst.'],['Stoma und peristomale Haut beobachten; Leckagen, Schmerz, Blutung und Ausscheidungsveränderung dokumentieren.','Selbstpflege mit Einwilligung schrittweise anleiten; Stomatherapie, Ernährungsberatung und psychosoziale Unterstützung vermitteln.','Körperbild, Intimität und Belastung ansprechen, ohne den Umgang vorzuschreiben.'],'Akute Bauchschmerzen, anhaltendes Erbrechen, starke Blutung, Fieber oder plötzlicher Stomastillstand rasch abklären lassen.','Ein Patient mit neuem Stoma hat Schmerzen, Hautreizungen und Angst vor dem ersten Wechsel. Wie gestaltest du Anleitung und Evaluation?','cancer',['Welche Beobachtung ist bei einem Stoma wichtig?',['Nur die Farbe des Beutels','Stomafarbe, Haut, Ausscheidung, Sitz der Versorgung und Beschwerden','Beutel unabhängig vom Füllstand selten entleeren','Leckagen ignorieren'],1,'Stoma und umgebende Haut sowie Ausscheidung und Versorgungssitz gemeinsam beurteilen.']),
 makeDisease('Leukämie und febrile Neutropenie','Onkologie und Pädiatrie','Leukämien sind bösartige Erkrankungen blutbildender Zellen. Chemotherapie kann eine Neutropenie mit hohem Infektionsrisiko verursachen.','Ausgeprägte Neutropenie vermindert die Abwehr gegen Erreger; Entzündungszeichen können trotz schwerer Infektion gering sein. Individueller Onkologieplan ist maßgeblich.',['Fieber, Schüttelfrost, ungewöhnliche Müdigkeit, Schleimhautläsionen oder Portveränderung ernst nehmen.','Fieber bei bekannter Neutropenie ist ein zeitkritischer onkologischer Notfall, auch wenn die Person zunächst stabil wirkt.'],['Blutbild, Kulturen und weitere Diagnostik nach ärztlichem Notfallstandard; Behandlung wird nicht durch routinemäßige Visite verzögert.','Hygiene-, Isolations- und Portmaßnahmen nach individueller Anordnung und Stationsstandard.'],['Temperatur, Vitalzeichen, Bewusstsein, Portstelle, Schmerz, Aufnahme und Ausscheidung erfassen; sofort Team alarmieren.','Aseptische Technik und Schutzmaßnahmen konsequent umsetzen, ohne unnötige Isolation außerhalb des Plans.','Mundpflege, Schmerzbehandlung und psychosoziale Unterstützung altersgerecht planen.'],'Fieber oder deutliche Zustandsänderung bei Neutropenie unverzüglich nach onkologischem Notfallplan eskalieren.','Ein Kind unter Chemotherapie mit Neutropenie hat Fieber und wirkt stiller. Was darf nicht bis zur Visite warten?','leukemia',['Was ist bei Fieber und bekannter Neutropenie entscheidend?',['Erst erneut in vier Stunden messen','Sofortige Beurteilung nach kinderonkologischem Notfallstandard','Kind isoliert allein lassen','Antibiotika eigenständig verabreichen'],1,'Febrile Neutropenie braucht sofortige fachliche Beurteilung und Behandlung nach lokalem Notfallstandard.']),
 makeDisease('Depression und Suizidalität','Psychische Gesundheit','Depression ist eine behandelbare Erkrankung mit anhaltend gedrückter Stimmung, Interessenverlust und weiteren psychischen oder körperlichen Symptomen.','Dauer, Schweregrad, Funktion und individuelle Belastungen variieren. Suizidgedanken können auftreten und müssen direkt angesprochen werden.',['Hoffnungslosigkeit, Schlaf-/Appetitveränderung, Antriebsminderung, Schuldgefühle, Konzentrationsprobleme oder Rückzug.','Äußerungen zu Lebensüberdruss, konkrete Pläne, verfügbare Mittel oder akute Selbstgefährdung ernst nehmen.'],['Diagnostik und Behandlung erfolgen multiprofessionell; Psychotherapie und Medikamente werden individuell vereinbart.','Suizidalität nicht aus einer einzelnen Aussage oder einem Versprechen ableiten; fachliche Einschätzung und Schutzplan nutzen.'],['Ruhig, direkt und wertfrei nach Gedanken, Absicht und Plan fragen; bei akuter Gefahr nicht allein lassen und sofort Team/Notfallhilfe einbeziehen.','Kleine erreichbare Tagesziele gemeinsam vereinbaren; Selbstpflege unterstützen, ohne zu drängen.','Angehörige nur mit Zustimmung einbeziehen, außer eine akute rechtliche Notlage verlangt anderes Vorgehen.'],'Konkrete Suizidabsicht, Plan, Vorbereitungen oder fehlende sichere Begleitung sofort eskalieren; Geheimhaltung nicht versprechen.','Eine Patientin sagt: „Es hat alles keinen Sinn mehr.“ Wie fragst du direkt nach Suizidgedanken und was tust du bei konkreter Gefahr?','depression',['Wie fragst du bei möglicher Suizidalität professionell nach?',['Gar nicht, um die Idee nicht auszulösen','Direkt, ruhig und wertfrei nach Suizidgedanken und Absicht fragen','Nur Angehörige fragen','Versprechen lassen, nichts zu tun'],1,'Direktes Nachfragen ermöglicht Einschätzung; ein Versprechen ersetzt keine fachliche Sicherheitsplanung.']),
 makeDisease('Psychose und Schizophrenie','Psychische Gesundheit','Eine Psychose ist eine schwere Störung der Realitätsprüfung. Schizophrenie ist eine mögliche Diagnose mit unterschiedlichen Verlaufsformen.','Erleben kann Wahn, Halluzinationen, Denkstörungen, Rückzug und Veränderungen von Antrieb umfassen. Diagnosen und Ursachen werden fachärztlich geklärt.',['Wahrnehmungen und Überzeugungen können für die betroffene Person real und belastend sein.','Suizidalität, Fremdgefährdung, starke Angst, Schlaflosigkeit, Flüssigkeitsmangel oder Unfähigkeit zur Selbstversorgung erfordern genaue Risikoeinschätzung.'],['Somatische Ursachen, Substanzen und Medikamente müssen je nach Situation mitabgeklärt werden.','Behandlung kann Medikamente, Psychotherapie, psychosoziale Unterstützung und Krisenplanung umfassen.'],['Ruhig, klar und respektvoll kommunizieren; Erleben anerkennen, ohne Wahn zu bestätigen oder aggressiv zu widersprechen.','Reize reduzieren, Wahlmöglichkeiten geben und Grenzen transparent halten; Sicherheit für alle Beteiligten planen.','Medikamentenwirkung/Nebenwirkungen und Selbstversorgung beobachten; Behandlung nur nach gültigem Plan.'],'Akute Selbst-/Fremdgefährdung, schwere körperliche Vernachlässigung oder Bewusstseinsveränderung erfordert sofortige fachliche Hilfe.','Ein Bewohner hört Stimmen und ist stark verängstigt. Wie reagierst du, ohne seine Wahrnehmung lächerlich zu machen oder zu bestätigen?','psychosis',['Welche Reaktion ist bei wahnhaftem Erleben hilfreich?',['Überzeugend diskutieren, bis die Person zustimmt','Gefühl anerkennen, ruhig bleiben und Sicherheit einschätzen','Die Person auslachen','Wahninhalte als Tatsache bestätigen'],1,'Belastung anerkennen und Sicherheit einschätzen, ohne den Wahn zu bestätigen.']),
 makeDisease('Alkoholabhängigkeit und Entzug','Psychische Gesundheit und Sucht','Alkoholabhängigkeit ist eine Erkrankung mit Kontrollverlust, starkem Verlangen und fortgesetztem Konsum trotz Schäden. Entzug kann medizinisch gefährlich sein.','Nach Reduktion oder Absetzen können autonome Symptome auftreten; schwere Verläufe reichen bis zu Krampfanfällen und Delir. Risiko hängt unter anderem von Vorgeschichte und körperlicher Situation ab.',['Tremor, Schwitzen, Unruhe, Schlaflosigkeit, Übelkeit, Herzrasen oder Blutdruckanstieg.','Krampfanfall, Halluzinationen, schwere Verwirrtheit, Fieber oder Kreislaufinstabilität sind Notfälle.'],['Entzugsschwere wird im Team standardisiert beurteilt; Diagnostik und Medikamente richten sich nach ärztlichem Protokoll.','Begleiterkrankungen, Mangelernährung, Flüssigkeit und Thiaminrisiko ärztlich berücksichtigen.'],['Konsum und letzten Trinkzeitpunkt wertfrei erheben; Veränderungen eng beobachten und sofort melden.','Sichere, reizangepasste Umgebung, Orientierung und nicht wertende Beziehungsgestaltung anbieten.','Nach Stabilisierung Motivation, Rückfallprävention und passende Beratungs-/Behandlungsangebote gemeinsam planen.'],'Entzugskrampf, Halluzinationen, Delir, Fieber oder instabile Vitalzeichen sofort als Notfall eskalieren.','Ein Patient nach abruptem Alkoholstopp wird zittrig, schwitzt stark und sieht Dinge, die nicht da sind. Welche Risiken und Zuständigkeiten beachtest du?','alcohol',['Was ist bei möglichem schwerem Alkoholentzug richtig?',['Patient allein lassen, damit Ruhe einkehrt','Sofortige fachliche Beurteilung organisieren und Verlauf eng beobachten','Alkohol als Pflegehandlung anbieten','Sedativa ohne Anordnung geben'],1,'Schwerer Entzug kann lebensbedrohlich sein; Behandlung gehört in einen medizinischen Überwachungsplan.']),
 makeDisease('Präeklampsie','Schwangerschaft und Geburt','Präeklampsie ist eine hypertensive Schwangerschaftserkrankung mit möglicher Beteiligung von Organen und Plazenta. Sie kann sich auch nach der Geburt entwickeln.','Neue Hypertonie nach der 20. Schwangerschaftswoche plus Proteinurie oder andere Organzeichen kann vorliegen. Schweregrade und Geburtszeitpunkt werden geburtshilflich beurteilt.',['Starker Kopfschmerz, Sehstörungen, Oberbauchschmerz, Übelkeit, Atemnot, hoher Blutdruck oder rasche Verschlechterung.','Krampfanfall, schwere Hypertonie, Lungenödem oder neurologische Zeichen sind Notfälle.'],['Blutdruck, Urin, Labor, mütterlicher Zustand und fetales Befinden werden im geburtshilflichen Team überwacht.','Medikamente, Krampfprophylaxe und Entbindungszeitpunkt sind ärztlich-geburtshilfliche Entscheidungen.'],['Warnzeichen sofort melden, Verlauf/Vitalwerte genau dokumentieren und Patientin begleiten.','Sorge ernst nehmen, verständlich erklären und Partner nach Zustimmung einbeziehen.','Nach der Geburt weiter auf Symptome und Blutdruckverlauf achten, da Erkrankung fortbestehen oder neu auftreten kann.'],'Starke Kopfschmerzen mit Sehstörung, Oberbauchschmerz, Krampfanfall oder schwerer Hypertonie sofort geburtshilflich eskalieren.','Eine Schwangere in der 34. Woche mit bekannter Hypertonie entwickelt Kopfschmerz und Flimmern vor den Augen. Was darf nicht abgewartet werden?','pregnancy',['Welche Aussage zu Präeklampsie ist richtig?',['Sie endet zwingend mit der Geburt sofort','Neue Warnzeichen müssen dringend geburtshilflich beurteilt werden','Proteinurie ist immer erforderlich','Kopfschmerz ist stets harmlos'],1,'Präeklampsie kann mehrere Organe betreffen; neue Warnzeichen erfordern rasche geburtshilfliche Einschätzung.']),
 makeDisease('Akute Pankreatitis','Verdauung und Stoffwechsel','Akute Pankreatitis ist eine Entzündung der Bauchspeicheldrüse, die leicht bis lebensbedrohlich verlaufen kann.','Häufige Ursachen sind Gallensteine und Alkohol; auch andere Auslöser sind möglich. Organdysfunktion und Komplikationen bestimmen die Schwere.',['Starker Oberbauchschmerz, oft gürtelförmig in den Rücken, Übelkeit und Erbrechen.','Kreislaufabfall, Atemnot, Fieber, zunehmender Schmerz oder Bewusstseinsänderung erfordern dringende Neubewertung.'],['Diagnose erfolgt durch Klinik, Labor und ggf. Bildgebung. Ursache und Schweregrad müssen medizinisch beurteilt werden.','Flüssigkeit, Analgesie und Ernährung folgen aktuellem Behandlungskonzept; keine pauschale Nahrungskarenz oder eigenständige Flüssigkeitsgabe ableiten.'],['Schmerz, Übelkeit, Vitalwerte, Ausscheidung, Flüssigkeitsbilanz und Atemsituation beobachten.','Lagerung und Ruhe nach Wunsch ermöglichen, verordnete Behandlung unterstützen und Wirkung/Nebenwirkungen dokumentieren.','Bei Verschlechterung rasch eskalieren und Nahrungs-/Flüssigkeitsplan mit dem Team abstimmen.'],'Kreislaufprobleme, Atemnot, Oligurie, starke Zunahme der Beschwerden oder Bewusstseinsstörung sofort melden.','Ein Patient mit akutem Oberbauchschmerz erbricht wiederholt und wird kreislaufinstabil. Welche Beobachtungen und Eskalation sind wichtig?','pancreatitis',['Welche Aussage zur akuten Pankreatitis ist sicher?',['Ernährung und Flüssigkeit immer eigenständig stoppen','Schweregrad und Plan individuell ärztlich abstimmen und Verschlechterung sofort melden','Schmerz ist kein relevanter Verlaufsparameter','Alkohol als Ursache sicher unterstellen'],1,'Therapie richtet sich nach Ursache und Schwere; Beobachtung und rechtzeitige Eskalation sind zentral.']),
 makeDisease('Dysphagie und Aspirationsrisiko','Neurologie und Pflege','Dysphagie ist eine Störung des Schluckens. Sie kann Essen, Trinken, Medikamentengabe und Sicherheit beeinträchtigen.','Ursachen umfassen neurologische Erkrankungen, Operationen, Tumoren und Schwäche. Aspiration kann still verlaufen und eine Pneumonie begünstigen.',['Husten, Räuspern, gurgelige Stimme, verlängerte Essenszeit, Speisereste im Mund oder wiederkehrende Pneumonien.','Akute Atemnot, Zyanose oder Erstickungszeichen sind Notfälle.'],['Schluckscreening und weiterführende Diagnostik durch qualifizierte Fachpersonen nach lokalem Standard.','Konsistenz, Lagerung und Hilfsmittel nur nach individuellem Befund/Plan; keine pauschale Andickung.'],['Bei Husten oder auffälliger Stimme orale Aufnahme unterbrechen, Atmung beurteilen und Fachteam informieren.','Mundraum kontrollieren, aufrechte Position und vereinbarte Hilfen nutzen; Medikamente nicht ohne Prüfung zerkleinern.','Betroffene und Angehörige verständlich anleiten und Vorlieben berücksichtigen.'],'Erstickungszeichen oder akute Atemnot sofort behandeln lassen; wiederholtes Husten beim Essen zeitnah abklären.','Ein Patient hustet beim Wassertrinken und die Stimme klingt danach feucht. Wie sicherst du die Situation, ohne unbewiesene Koständerung?','dysphagia',['Was ist bei neuem Husten beim Trinken sicher?',['Dünne Flüssigkeit weiterreichen','Aufnahme unterbrechen, Atmung beurteilen und Schluckabklärung veranlassen','Flüssigkeit eigenständig dauerhaft andicken','Tabletten mörsern'],1,'Sicherheit zuerst; Konsistenz und Medikamentengabe benötigen individuelle fachliche Prüfung.']),
 makeDisease('Chronische Wunde und diabetisches Fußsyndrom','Haut, Wunden und Stoffwechsel','Chronische Wunden heilen verzögert; beim diabetischen Fuß kommen Neuropathie, Durchblutungsstörung und Infektion als Risiken zusammen.','Ursachen wie venöse Insuffizienz, arterielle Durchblutungsstörung, Druck oder Diabetes müssen erkannt werden. Die Wundbehandlung richtet sich nach Ursache und Gesamtziel.',['Wunde, Wundrand, Exsudat, Geruch, Schmerz, Temperatur und Umgebungshaut systematisch beobachten.','Rötung, Überwärmung, rasche Ausbreitung, Fieber, Nekrose oder plötzlich zunehmender Schmerz dringlich abklären.'],['Ätiologie, Durchblutung, Sensibilität, Druckbelastung und Infektionszeichen fachlich beurteilen.','Wundauflage und Kompression nur nach Befund/Plan; bei arterieller Minderperfusion kann Kompression gefährlich sein.'],['Wunde nach Standard versorgen, aseptische Technik und Einwilligung beachten; Verlauf vergleichbar dokumentieren.','Druckentlastung, Schuhwerk, Blutzuckerplan und Mobilität im Team abstimmen.','Schmerz ernst nehmen und regelmäßige Kontrolle/Anschlussversorgung sicherstellen.'],'Fieber, rasche Rötung, übler Geruch mit Verschlechterung, Nekrose oder kalter/blasser Fuß erfordern dringende Abklärung.','Eine Person mit Diabetes hat eine schmerzlose Fußwunde und einen kühlen Fuß. Welche Ursachen und Risiken müssen vor einer Maßnahme geprüft werden?','wounds',['Was ist vor einer Kompression bei einer Unterschenkelwunde wichtig?',['Kompression immer beginnen','Durchblutung und Indikation fachlich prüfen lassen','Wunde unabhängig von Ursache abdecken','Schmerzen ignorieren'],1,'Kompression ist nicht bei jeder Ursache geeignet; Durchblutung und ärztlich/pflegerischer Plan müssen berücksichtigt werden.']),
 makeDisease('Multiple Sklerose','Neurologie','Multiple Sklerose ist eine chronisch-entzündliche Erkrankung des zentralen Nervensystems mit unterschiedlichen Verläufen.','Entzündungsherde können Sehnerven, Gehirn und Rückenmark betreffen. Symptome entstehen je nach Ort und Aktivität der Läsion.',['Sehstörung, Sensibilitätsveränderung, Kraftminderung, Spastik, Koordinations- oder Blasenprobleme und ausgeprägte Fatigue.','Neue schwere neurologische Symptome, akute Atem-/Schluckprobleme oder Fieber mit deutlicher Verschlechterung abklären.'],['Diagnose und verlaufsmodifizierende Therapie erfolgen neurologisch. Schub, Infekt und Pseudoschub müssen unterschieden werden.','Rehabilitation und symptomatische Behandlung werden an Funktion und Lebenszielen ausgerichtet.'],['Belastung, Fatigue, Mobilität, Sturzrisiko, Schmerz, Blasenfunktion und Selbstständigkeit erfassen.','Energie einteilen, Ruhephasen und Hilfsmittel planen; Aktivitäten an Tagesform anpassen.','Selbstbestimmung und Teilhabe erhalten, Angehörige nur mit Zustimmung einbeziehen.'],'Plötzlicher neuer Sehverlust, deutliche Lähmung, Schluck- oder Atemstörung sofort fachlich abklären.','Eine Patientin mit MS ist nach einem Infekt deutlich erschöpfter und unsicher beim Gehen. Wie unterscheidest du Verlauf, Auslöser und Hilfebedarf?','guidelines',['Was hilft bei MS-bedingter Fatigue?',['Belastung unabhängig von Tagesform steigern','Aktivitäten und Pausen gemeinsam an Tagesform anpassen','Alle Bewegung vermeiden','Selbstständigkeit grundsätzlich übernehmen'],1,'Energie- und Belastungsmanagement ist individuell; Bewegung und Teilhabe sollen nicht pauschal ausgeschlossen werden.']),
 makeDisease('Appendizitis im Kindesalter','Pädiatrie und Verdauung','Appendizitis ist eine Entzündung des Wurmfortsatzes. Bei Kindern können Beschwerden atypisch sein und sich rasch verändern.','Schmerz kann zunächst diffus und später im rechten Unterbauch stärker sein; andere Ursachen des akuten Bauchschmerzes sind möglich.',['Bauchschmerz, Appetitlosigkeit, Übelkeit/Erbrechen und Fieber; kleine Kinder können unspezifisch reagieren.','Zunehmender Schmerz, Abwehrspannung, blasses oder schwer krank wirkendes Kind erfordern dringende Abklärung.'],['Klinische Untersuchung, Labor und Bildgebung richten sich nach Befund; Diagnose/Operationsentscheidung trifft das Behandlungsteam.','Bis zur Klärung keine Nahrung oder Medikamente gegen ärztliche Vorgabe anbieten; lokale Anordnungen befolgen.'],['Schmerz und Verlauf kindgerecht erfragen, Vitalzeichen und Verhalten beobachten und Bezugsperson einbeziehen.','Kind beruhigen, verständlich erklären und altersgerechte Wahlmöglichkeiten geben.','Einwilligungs-/Beteiligungsregeln und Kindeswohl beachten; Veränderungen sofort melden.'],'Starke zunehmende Bauchschmerzen, Abwehrspannung, Kreislaufzeichen oder wiederholtes Erbrechen sofort eskalieren.','Ein sechsjähriges Kind hat zunehmende Bauchschmerzen und möchte nicht laufen. Wie schätzt du Dringlichkeit, Kommunikation und Familienbedarf ein?','appendicitis',['Was ist bei Verdacht auf Appendizitis bei einem Kind sinnvoll?',['Schmerzmittel geben und Zuhause abwarten','Dringende medizinische Abklärung organisieren und Verlauf beobachten','Abführmittel anbieten','Bauch kräftig massieren'],1,'Akuter Bauchschmerz bei Kindern verlangt klinische Beurteilung; eigenständige Behandlung kann verzögern.'])
];

const makeCareTopic=(...args)=>{const x=makeDisease(...args);x.category='Pflegeverfahren';return x};
window.pfDiseaseEntries.push(
 makeCareTopic('Tracheostoma, Trachealkanüle und Cuff','Atemwegspflege','Ein Tracheostoma ist eine operativ angelegte Öffnung der Trachea. Eine Trachealkanüle hält den Zugang offen; ein Cuff dichtet die Trachea für bestimmte Beatmungssituationen ab.','Tracheotomie und totale Laryngektomie sind nicht gleichzusetzen. Nach totaler Laryngektomie ist das Stoma der einzige Atemweg zur Lunge. Ein geblockter Cuff verhindert Aspiration nicht zuverlässig.',['Atemnot, Sekretverlegung, undichte Verbindung, Blutung, Hautschädigung oder veränderte Kanülenlage.','Cuffdruck, Kanülenwechsel und Absaugen erfolgen nur nach Qualifikation, Verordnung und lokalem Standard.'],['Indikation, Kanülentyp, Stomapflege, Sprech-/Schluckstatus und individuelle Notfallausrüstung prüfen.','Bei totaler Laryngektomie darf Sauerstoff/Beatmung nicht ausschließlich über Mund oder Nase erfolgen.'],['Atemweg, Atemarbeit, Sekret, Stoma, Kanülenfixierung und Cuff gemäß Plan beobachten.','Befeuchtung, Mundpflege, Kommunikation und Absaugmaterial nach Standard sicherstellen.','Cuffdruck nicht nach Gefühl ändern; Druckmessung/Anpassung durch geschulte Personen nach lokalem Protokoll.'], 'Atemnot, Kanülenverlegung/-verlust, massive Blutung oder rasch sinkende Sättigung: sofort Notfallteam; individuellen Atemwegsnotfallplan nutzen.','Eine tracheotomierte Person wird plötzlich unruhig, kann kaum sprechen und die Sättigung fällt. Welche Sofortbeurteilung und Hilfe organisierst du?','guidelines',['Was gilt für den Cuff einer Trachealkanüle?',['Ein geblockter Cuff verhindert Aspiration sicher','Cuffmanagement erfolgt nach individuellem Plan und verhindert Aspiration nicht zuverlässig','Cuffdruck nach Gefühl einstellen','Cuff immer dauerhaft entblocken'],1,'Der Cuff unterstützt je nach Indikation die Beatmung, ist aber kein sicherer Aspirationsschutz.']),
 makeCareTopic('Thoraxdrainage','Atmung und Pflegeverfahren','Eine Thoraxdrainage leitet Luft oder Flüssigkeit aus dem Pleuraspalt ab und unterstützt die Entfaltung der Lunge.','Das System arbeitet als geschlossenes Drainagesystem. Lage, Sog und Umgang richten sich nach Anlage, ärztlicher Anordnung und lokalem Standard.',['Atemnot, zunehmender Schmerz, sinkende Sauerstoffsättigung, neue Schwellung unter der Haut oder auffällige Fördermenge.','Luftleckzeichen, fehlende Schwankung oder plötzliches Sistieren sind im Kontext zu beurteilen; nicht automatisch die Drainage manipulieren.'],['Ausgangslage, Drainagetyp, Sogvorgabe, Menge und Beschaffenheit des Sekrets sowie Anschlüsse prüfen.','Bildgebung und Entscheidung über Sog, Abklemmen oder Entfernung erfolgen durch das Behandlungsteam.'],['System aufrecht und unter Thoraxniveau halten, Schlauchverlauf und Verbindungen auf Zug, Knick und Diskonnektion kontrollieren.','Atmung, Schmerz, Haut, Fördermenge und Zeitpunkte dokumentieren; Mobilisation nur mit gesichertem System.','Drainage nie routinemäßig abklemmen, ausstreichen oder entfernen; nur nach ausdrücklicher Anordnung/Notfallstandard handeln.'],'Akute Atemnot, Diskonnektion, starke Blutung oder rasche Verschlechterung sofort melden und Notfallstandard aktivieren.','Bei einer Patientin mit Thoraxdrainage nimmt die Atemnot zu und im Schlauch ist kein sichtbarer Flüssigkeitsfluss. Was beurteilst du, ohne das System eigenständig zu manipulieren?','guidelines',['Was ist bei einer Thoraxdrainage grundsätzlich sicher?',['Drainage routinemäßig abklemmen','Systemlage/Verbindungen prüfen, Atmung beurteilen und Auffälligkeiten melden','Schlauch kräftig ausstreichen','Sog eigenständig verändern'],1,'Drainagesysteme werden nicht ohne Anordnung manipuliert; klinische Verschlechterung und Systemauffälligkeiten sind sofort weiterzugeben.']),
 makeCareTopic('CABCDE bei Trauma und vitaler Gefährdung','Notfallpflege','CABCDE priorisiert zuerst eine lebensbedrohliche Blutung, danach Atemweg, Atmung, Kreislauf, neurologischen Status und vollständige Untersuchung.','Das Schema unterstützt strukturiertes Vorgehen; lebensbedrohliche Probleme werden erkannt und behandelt, bevor zur nächsten Stufe übergegangen wird.','C – kritische Blutung; A – Atemweg; B – Atmung; C – Kreislauf; D – neurologischer Zustand; E – Entkleiden/Umgebung.',['Bei schwerem Trauma zuerst Eigenschutz, Hilfe und lokalen Alarmierungsweg sicherstellen.','Beurteilung und Maßnahmen wiederholen, weil sich der Zustand rasch ändern kann.'],['Ursachen und Schwere werden durch Rettungsdienst/Notfallteam abgeklärt; Vitalwerte, Verletzungsmechanismus und Zeitverlauf strukturiert übergeben.','Maßnahmen richten sich nach Qualifikation, Ausbildung und lokalem Notfallstandard.'],['Starke äußere Blutung sofort nach Standard kontrollieren und Hilfe alarmieren.','Bewusstsein, Atmung, Kreislauf, Haut, Schmerz und Temperatur im Verlauf beobachten; Hypothermie vermeiden.','Bei Veränderung erneut von C beginnen und alle Maßnahmen/Zeitpunkte dokumentieren.'],'Lebensbedrohliche Blutung, Atemwegsverlegung, Schockzeichen oder Bewusstseinsabfall sofort eskalieren.','Nach einem Sturz mit starker Blutung wirkt ein Patient zunehmend blass und verwirrt. Wie setzt du CABCDE ein und welche Informationen übergibst du?','guidelines',['Was hat im CABCDE-Schema zuerst Vorrang?',['Neurologische Untersuchung','Kontrolle einer lebensbedrohlichen Blutung','Vollständige Dokumentation','Schmerzeinschätzung'],1,'Das vorangestellte C steht für kritische Blutung; parallel unverzüglich Hilfe organisieren.'])
);
